#include "r6_cli.hpp"
#include "wire.hpp"
#include <iostream>
using namespace zkgpt;
int main(int argc,char**argv){try{r1::require(argc>=5,"usage: r6_model_verify STATEMENT PROOF --blocks1|12 --trusted-anchor FILE --anchor-sha256 HEX --model-manifest FILE");auto o=r6::options(argc,argv,3);r1::require(!o.plan_only,"use r6_model_plan for metadata");r6::requireExecution(o);r6::limits(o,false);r1::init();LLM nn(o.blocks,12,64,768,3072);r6::configure(nn);auto c=nn.buildPublicCircuit();auto plan=r2::planModelQueries(c,nn.getWitnessRegistry(),nn.parameterRegions(),r1::ExpProfile::LegacyClampOne);r6::auditGraph(c,nn,plan);auto anchor=r6::loadAnchor(o.anchor,o.pin,o.manifest,plan);r6::preflight(o,r6::resources(c,nn,plan),plan,"verifier");auto[g,s]=r2::parseStatement(r1::readFile(argv[1]));
 const auto&a=g.model_shape,&b=plan.shape;r1::require(g.circuit_fingerprint==fingerprintCircuit(c) && g.val0_log_size==r1::log2exact(plan.master.padded) && g.output_evaluation.isZero(),"R6 GKR circuit/output identity mismatch");r1::require(a.sequence_length==b.sequence_length && a.layer_count==b.layer_count && a.head_count==b.head_count && a.head_dimension==b.head_dimension && a.hidden_dimension==b.hidden_dimension && a.mlp_dimension==b.mlp_dimension,"R6 model shape mismatch");r1::require(s.input.public_values.size()>=65536 && !s.input.children.empty(),"R6 missing public X/Y/W");std::vector<Fr>x,y;for(std::size_t i=0;i<32768;++i){x.push_back(s.input.public_values[i].value);y.push_back(s.input.public_values[32768+i].value);}r5b::requireAnchorW(anchor,s.input.children.back().commitment);r2::requireModelQueryStatement(plan,s,anchor.w,x,y,anchor.model_id);auto progress=[&](const std::string&phase){r6::runtimeCheck(o);std::cerr<<"PHASE "<<phase<<'\n';};auto proof=r2::parseProof(g,s,r1::readFile(argv[2]));auto claims=r2::verifyR2(c,g,s,proof,progress);r1::require(claims.size()==r2::modelResources(c,plan).terminals,"R6 incomplete GKR input terminal coverage");std::cout<<"ACCEPT R6 blocks="<<o.blocks<<" GKR+production Lasso+bridge+unified input,externally OPERATOR-TRUSTED W; candidate only\n";return 0;
 }catch(const std::exception&e){std::cerr<<"REJECT "<<e.what()<<'\n';return 2;}}
